#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto apply = [&](int x, int y){
        assert(x>0 && y>0 && x+y<n);
        ops.push_back({x,y});
        vector<int> np;
        // [suffix | middle | prefix]
        // suffix = p[n-y .. n-1], middle = p[x .. n-y-1], prefix = p[0..x-1]
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
    };

    for(int target=0; target<n-2; target++){
        int pos=-1;
        for(int i=target;i<n;i++) if(p[i]==target+1){pos=i;break;}
        if(pos==target) continue;

        // We want to move p[pos] to position target
        // Strategy: use one op to move element to the end (position n-1), then one op to place it at target

        if(pos==n-1){
            // Element already at end, just need one op to place it at target
            // x=target+1, y=1, need target+1+1<n => target<n-2 (guaranteed by loop)
            // After op: [p[n-1]] ++ p[target+1..n-2] ++ p[0..target]
            // p[n-1] goes to position 0... we want it at target
            // Instead: x=target, y=1 if target>0
            // Result: [p[n-1]] ++ p[target..n-2] ++ p[0..target-1] => element at pos 0, not target
            // Hmm. Let me think differently.
            // We want element at n-1 to go to position target.
            // After op with x,y: suffix of length y goes to front. Element at n-1 is last of suffix.
            // Element at n-1 goes to position y-1 in new array.
            // We want y-1=target => y=target+1. Then x can be anything with x+y<n, x>0.
            // x=1, y=target+1, need 1+target+1<n => target<n-2 ✓
            if(target+1>0 && 1+target+1<n){
                apply(1, target+1);
                continue;
            }
        }

        // Move element from pos to n-1:
        // Element at pos. In the new array after op(x,y), prefix p[0..x-1] goes to end.
        // If pos < x, element goes to position (n-x) + pos = n-x+pos. Want n-x+pos=n-1 => x=pos+1.
        // Need x+y<n => pos+1+y<n => y<n-pos-1. Also y>0. So y=1 if n-pos-1>1 i.e. pos<n-2.
        if(pos<n-2){
            apply(pos+1, 1);
            // Now element is at n-1; place it at target
            if(target==0){ apply(1, 1); /* goes to pos 0? No. y=1=>element at pos0. x=1. Hmm */ }
            apply(1, target+1);
        } else { // pos==n-2
            // x=1,y=1: moves p[n-1] to front, p[0] to end. Element at n-2 stays at n-2. Not helpful.
            // x=n-2,y=1: element at n-2 goes to end (pos n-x+pos=n-(n-2)+(n-2)=n-1? No: n-x+pos only if pos<x). x=n-2, pos=n-2 => pos<x is false(pos==x). Middle=p[n-2..n-2]=[p[n-2]]. Element stays in middle at position y+0=1. Hmm.
            // x=pos+1=n-1,y must satisfy x+y<n => y<1, impossible.
            // Use x=1,y=2: suffix=[p[n-2],p[n-1]], element at position 0 of new array. Then place.
            apply(1, 2);
            // element now at position 0
            // place at target: need it from 0 to target
            // pos=0 in prefix. After op(x,y): goes to n-x+0=n-x. Want n-x=target => x=n-target.
            // y>0, x+y<n => y<n-x=target. y=1 if target>1. If target==0, already done. If target==1, y must be <1, impossible.
            int cur=0;
            for(int i=0;i<n;i++) if(p[i]==target+1){cur=i;break;}
            if(cur==target) continue;
            if(cur==0 && target>0){
                int x2=n-target, y2=1;
                if(x2>0&&y2>0&&x2+y2<n) apply(x2,y2);
                else { apply(1,1); apply(1,target+1); }
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
